// Node: "Queue for Deduplication (Optimized)"
// Checks if kill exists in Redis BEFORE queuing to save worker CPU.

const Redis = require('ioredis');
let redis;

// 1. Configuration
const QUEUE_KEY = 'intel:queue:archive'; 
const PROCESSED_HASH_KEY = 'intel:kill:data'; // Where you store processed kills

const items = $input.all();
const killsToCheck = []; 

// 2. Extract all IDs from the zKill History Files
for (const item of items) {
    const historyData = item.json; 

    if (typeof historyData !== 'object' || historyData === null || Array.isArray(historyData)) continue;

    const killIds = Object.keys(historyData);
    for (const killId of killIds) {
        const hash = historyData[killId];
        const numericKillId = parseInt(killId, 10);

        if (numericKillId && hash) {
            killsToCheck.push({
                kill_id: numericKillId,
                hash: hash
            });
        }
    }
}

if (killsToCheck.length === 0) {
    console.log('[Archive] No kills found in history file.');
    return [{ json: { status: 'empty' } }];
}

console.log(`[Archive] Checking ${killsToCheck.length} kills against database...`);

try {
    redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 5000 });

    // 3. Pipeline Check (Super Fast)
    const checkPipeline = redis.pipeline();
    killsToCheck.forEach(k => checkPipeline.hexists(PROCESSED_HASH_KEY, String(k.kill_id)));
    const results = await checkPipeline.exec();

    // 4. Filter - Keep only MISSING kills
    const killsToQueue = [];
    let alreadyExistsCount = 0;

    results.forEach((res, index) => {
        // res[1] === 1 means it exists. We want it if it is 0.
        if (res[1] === 0) {
            killsToQueue.push(killsToCheck[index]);
        } else {
            alreadyExistsCount++;
        }
    });

    console.log(`[Archive] Filtered Results: ${alreadyExistsCount} exist, ${killsToQueue.length} are new and will be queued.`);

    if (killsToQueue.length > 0) {
        const queuePipeline = redis.pipeline();
        for (const kill of killsToQueue) {
            queuePipeline.rpush(QUEUE_KEY, JSON.stringify(kill));
        }
        await queuePipeline.exec();
    }

    return [{ json: { new_kills_queued: killsToQueue.length, total_checked: killsToCheck.length } }];

} catch (e) {
    console.error('ERROR in Archive Checker:', e.message);
    // In case of error, forward original items to allow processing anyway
    return items;
} finally {
    if (redis) {
        redis.quit();
    }
}

// Node: "Comprehensive Prune & Heal"
// Phase 1: Deletes killmails older than 30 days from ALL associated data structures.
// Phase 2: Scans for and removes any orphaned data missing from the primary index.

const Redis = require('ioredis');

// --- Configuration ---
const DAYS_TO_KEEP = 30;
const BATCH_SIZE = 500; // Process 500 items at a time.
const REDIS_CONFIG = { host: 'redis', port: 6379, db: 0, connectTimeout: 5000, maxRetriesPerRequest: 3 };

// --- Helper for Comprehensive Deletion ---
const comprehensivelyDelete = (killmails, pipeline, report, type) => {
    if (!Array.isArray(killmails) || killmails.length === 0) {
        return;
    }

    const idsToDelete = killmails.map(km => String(km.killmail_id));

    // 1. Queue deletion from the main data hash and primary time index
    pipeline.hdel('intel:kill:data', ...idsToDelete);
    pipeline.zrem('intel:kills:all', ...idsToDelete);
    pipeline.zrem('intel:kills:24h_stats', ...idsToDelete);
    report.summary.data_hashes_deleted += idsToDelete.length;
    report.summary.index_entries_removed += idsToDelete.length * 2;

    // 2. For each kill, queue deletion from all its specific indexes
    for (const km of killmails) {
        const killIdStr = String(km.killmail_id);

        if (type === 'age') {
            report.summary.pruned_by_age++;
        } else if (type === 'orphan') {
            report.summary.healed_orphans++;
        }

        // Classes
        if (km.victim_ship_class) pipeline.zrem(`intel:losses:ship_class:${km.victim_ship_class}`, killIdStr);
        if (km.victim_ship_class_detailed) pipeline.zrem(`intel:losses:ship_class_detailed:${km.victim_ship_class_detailed}`, killIdStr);

        // ISK Value
        let valKey = 'sub10m';
        if (km.total_value >= 50e9) valKey = '50b';
        else if (km.total_value >= 20e9) valKey = '20b-50b';
        else if (km.total_value >= 10e9) valKey = '10b-20b';
        else if (km.total_value >= 1e9) valKey = '1b-10b';
        else if (km.total_value >= 100e6) valKey = '100m-1b';
        else if (km.total_value >= 10e6) valKey = '10m-100m';
        pipeline.zrem(`intel:kills:isk:${valKey}`, killIdStr);

        // Geo
        if (km.space_type) pipeline.zrem(`intel:kills:space:${km.space_type}`, killIdStr);
        if (km.solar_system_id) pipeline.zrem(`intel:kills:system:${km.solar_system_id}`, killIdStr);
        if (km.region_id) pipeline.zrem(`intel:kills:region:${km.region_id}`, killIdStr);
        if (km.constellation_id) pipeline.zrem(`intel:kills:constellation:${km.constellation_id}`, killIdStr);

        // Time & Fleet
        if (km.kill_hour !== undefined) pipeline.zrem(`intel:kills:hour:${km.kill_hour}`, killIdStr);
        if (km.kill_day !== undefined) pipeline.zrem(`intel:kills:day:${km.kill_day}`, killIdStr);
        if (km.fleet_size) pipeline.zrem(`intel:kills:fleet:${km.fleet_size}`, killIdStr);

        // Alliances, Corps, Chars
        const involvedEntities = new Set();
        if (km.victim) {
            if (km.victim.alliance_id) involvedEntities.add({ type: 'alliance', id: km.victim.alliance_id });
            if (km.victim.corporation_id) involvedEntities.add({ type: 'corporation', id: km.victim.corporation_id });
            if (km.victim.character_id && !km.victim.is_npc) involvedEntities.add({ type: 'character', id: km.victim.character_id });
            if (km.victim.ship_type_id) pipeline.zrem(`intel:losses:ship:${km.victim.ship_type_id}`, killIdStr);
        }
        (km.attackers || []).forEach(a => {
            if (a.alliance_id) involvedEntities.add({ type: 'alliance', id: a.alliance_id });
            if (a.character_id && !a.is_npc) involvedEntities.add({ type: 'character', id: a.character_id });
            if (a.ship_class) pipeline.zrem(intel:kills:ship_class:\, killIdStr);
            if (a.ship_class_detailed) pipeline.zrem(intel:kills:ship_class_detailed:\, killIdStr);
        });

        for (const entity of involvedEntities) {
            if(entity.type === 'alliance') {
                pipeline.zrem(`intel:followed:alliance:${entity.id}`, killIdStr);
                pipeline.zrem(`intel:losses:alliance:${entity.id}`, killIdStr);
                pipeline.zrem(`intel:kills:alliance:${entity.id}`, killIdStr);
                pipeline.zrem(`intel:stats:alliance:kills_by_value:${entity.id}`, killIdStr);
                pipeline.zrem(`intel:stats:alliance:losses_by_value:${entity.id}`, killIdStr);
            }
            if (entity.type === 'character') {
                pipeline.zrem(`intel:losses:character:${entity.id}`, killIdStr);
                pipeline.zrem(`intel:kills:character:${entity.id}`, killIdStr);
            }
            if (entity.type === 'corporation') {
                pipeline.zrem(`intel:losses:corporation:${entity.id}`, killIdStr);
            }
        }
    }
};

// --- Main Execution Logic ---
const redis = new Redis(REDIS_CONFIG);
const report = {
    status: 'started',
    summary: {
        killmails_to_prune: 0,
        pruned_by_age: 0,
        healed_orphans: 0,
        data_hashes_deleted: 0,
        index_entries_removed: 0,
    },
    errors: [],
};
try {
    console.log("--- Starting Comprehensive Prune & Heal Script ---");
    await redis.ping();

    // --- PHASE 1: Pruning by Age ---
    console.log("--- Phase 1: Pruning by Age (older than 30 days) ---");
    const cutoffScore = Math.floor((Date.now() - (DAYS_TO_KEEP * 24 * 60 * 60 * 1000)) / 1000);
    const idsToPrune = await redis.zrangebyscore('intel:kills:all', 0, cutoffScore);
    report.summary.killmails_to_prune = idsToPrune.length;

    if (idsToPrune.length > 0) {
        console.log(`[Prune] Found ${idsToPrune.length} killmails to prune by age. Processing in batches of ${BATCH_SIZE}...`);
        for (let i = 0; i < idsToPrune.length; i += BATCH_SIZE) {
            const batchIds = idsToPrune.slice(i, i + BATCH_SIZE);
            const batchDataJson = await redis.hmget('intel:kill:data', ...batchIds);
            const killmailsInBatch = batchDataJson.map(json => json ? JSON.parse(json) : null).filter(Boolean);

            const deletionPipeline = redis.pipeline();
            comprehensivelyDelete(killmailsInBatch, deletionPipeline, report, 'age');
            await deletionPipeline.exec();

            console.log(`[Prune] Batch ${Math.floor(i / BATCH_SIZE) + 1} complete. Pruned ${killmailsInBatch.length} old killmails.`);
        }
    } else {
        console.log("[Prune] No killmails older than 30 days found to prune.");
    }
    console.log("--- Phase 1 Complete ---");

    // --- PHASE 2: Healing Orphaned Data ---
    console.log("--- Phase 2: Healing Orphaned Data (verifying all remaining hashes) ---");
    let orphanCursor = '0';
    let totalScanned = 0;
    do {
        const [nextCursor, keys] = await redis.hscan('intel:kill:data', orphanCursor, 'COUNT', BATCH_SIZE);
        orphanCursor = nextCursor;
        const batchIds = keys.filter((_, i) => i % 2 === 0);
        totalScanned += batchIds.length;

        if (batchIds.length > 0) {
            const scores = await redis.zmscore('intel:kills:all', ...batchIds);
            const orphanIds = batchIds.filter((id, index) => scores[index] === null);

            if (orphanIds.length > 0) {
                console.log(`[Heal] Found ${orphanIds.length} orphans in this batch. Removing...`);
                const orphanDataJson = await redis.hmget('intel:kill:data', ...orphanIds);
                const orphanKillmails = orphanDataJson.map(json => json ? JSON.parse(json) : null).filter(Boolean);

                const healPipeline = redis.pipeline();
                comprehensivelyDelete(orphanKillmails, healPipeline, report, 'orphan');
                await healPipeline.exec();
            }
        }
        if(totalScanned > 0) console.log(`[Heal] Scanned ${totalScanned} total hashes for orphans...`);
    } while (orphanCursor !== '0');
    console.log("--- Phase 2 Complete ---");

    report.status = 'success';
    console.log("✅ Comprehensive Pruning & Healing complete.");

} catch (e) {
    report.status = 'error';
    report.errors.push({ message: e.message, stack: e.stack });
    console.error("❌ CRITICAL ERROR during prune/heal process:", e);
} finally {
    if (redis) await redis.quit();
}

return [{ json: report }];

// Node: "1. Get Last 3 Days (Fixed)"
// Outputs 3 valid date strings for zKillboard history files.

const datesToCheck = [];
const today = new Date(); 

// Loop for 1 day ago, 2 days ago, and 3 days ago
for (let i = 1; i <= 3; i++) {
    const date = new Date(today);
    date.setUTCDate(date.getUTCDate() - i); // Go back i days

    const year = date.getUTCFullYear();
    const month = String(date.getUTCMonth() + 1).padStart(2, '0');
    const day = String(date.getUTCDate()).padStart(2, '0');

    // Format: YYYYMMDD
    const dateString = `${year}${month}${day}`;

    datesToCheck.push({
        json: {
            dateString: dateString,
            friendlyDate: date.toISOString().split('T')[0]
        }
    });
}

return datesToCheck;
